var memStorage = require('./memStorage');
// const { LocalStorage } = require('node-localstorage');

exports = function(type) {
    type = type || 'local';
    var ret;


    // Create separate storage instances for localStorage and sessionStorage
    // const localStorage = new LocalStorage('./local');
    // const sessionStorage = new LocalStorage('./session');

    if (typeof window !== 'undefined') {
    switch (type) {
        case 'local':
            ret = window.localStorage;//localStorage//window.localStorage;
            break;
        case 'session':
            ret = window.sessionStorage;//sessionStorage//window.sessionStorage;
            break;
    }}
    try {
        var x = 'test-localStorage-' + Date.now();
        ret.setItem(x, x);
        var y = ret.getItem(x);
        ret.removeItem(x);
        if (y !== x) throw new Error();
    } catch (e) {
        return memStorage;
    }
    return ret;
};

module.exports = exports;
